json read_fixture () {
    const std::filesystem::path path =
    std::filesystem::path (__FILE__).parent_path () / "fixtures" / "import-conformance.json";
    std::ifstream file (path);
    EXPECT_TRUE (file.is_open ()) << "missing fixture: " << path;
    json fixture;
    file >> fixture;
    return fixture;
}

void sort_examples (json& collections) {
    for (json& collection : collections) {
        for (json& request : collection.at ("requests")) {
            if (!request.contains ("examples")) {
                continue;
            }
            json& examples = request.at ("examples");
            std::stable_sort (examples.begin (), examples.end (),
            [] (const json& a, const json& b) {
                return a.at ("status").get<int> () < b.at ("status").get<int> ();
            });
        }
        sort_examples (collection.at ("children"));
    }
}

/// @p variables without each row's `createdAt`: a Postman import stamps it from
/// the clock (#3252), so no recorded answer can hold it.
/// `PostmanImport.StampsEachVariableRowInFileOrder` pins the stamps instead.
json without_created_at (json variables) {
    for (auto row = variables.begin (); row != variables.end (); ++row) {
        if (row->is_object ()) {
            row->erase ("createdAt");
        }
    }
    return variables;
}

void strip_collection_created_at (json& collections) {
    for (json& collection : collections) {
        if (collection.contains ("variables")) {
            collection["variables"] =
            without_created_at (collection.at ("variables"));
        }
        strip_collection_created_at (collection.at ("children"));
    }
}

/// The comparable form of a result: plain `json` (whose objects compare by key,
/// not by insertion order) with the two normalisations above applied, and
/// every variable's clock stamp removed.
json comparable (const nlohmann::ordered_json& result) {
    json out               = json::parse (result.dump ());
    out["meta"]["skipped"] = skip_counts (out.at ("meta").at ("skipped"));
    out["meta"].erase ("nonExecutableAuthRequests");
    out["meta"].erase ("nonExecutableAuthFolders");
    out["meta"].erase ("nonExecutableAuthCollection");
    out["meta"].erase ("unsupportedScriptApis");
    sort_examples (out.at ("collections"));
    strip_collection_created_at (out.at ("collections"));
    for (json& environment : out.at ("environments")) {
        environment["variables"] =
        without_created_at (environment.at ("variables"));
    }
    out["globals"] = without_created_at (out.at ("globals"));
    return out;
}

ImportOptions options_of (const json& declared) {
    ImportOptions options;
    options.import_environments = declared.at ("importEnvironments").get<bool> ();
    options.import_scripts = declared.at ("importScripts").get<bool> ();
    return options;
}

ImportSource source_of (const json& entry) {
    ImportSource source;
    if (const auto declared = entry.find ("source"); declared != entry.end ()) {
        if (const auto found = declared->find ("fileName"); found != declared->end ()) {
            source.file_name = found->get<std::string> ();
        }
        if (const auto found = declared->find ("sourceUrl"); found != declared->end ()) {
            source.source_url = found->get<std::string> ();
        }
        if (const auto found = declared->find ("unresolvedRefs");
        found != declared->end ()) {
            source.unresolved_refs = found->get<int> ();
        }
    }
    return source;
}

TEST (ImportConformance, MatchesTheParsersItReplaced) {
    const json fixture = read_fixture ();
    ASSERT_FALSE (fixture.at ("cases").empty ())
    << "an empty corpus proves nothing";

    for (const json& entry : fixture.at ("cases")) {
        const std::string name = entry.at ("name").get<std::string> ();
        const ImportParse parsed =
        parse_import (entry.at ("document").get<std::string> (),
        options_of (entry.at ("options")), source_of (entry));
        ASSERT_TRUE (parsed.ok ()) << name << ": " << parsed.error;

        // The fixture records what `POST /import/parse` answers, which derives
        // each file reference's `unresolved` (#2356); with no folder allowed
        // and no file picked, every path the corpus names reads as unresolved.
        json answered = parsed.result;
        vayu::core::derive_import_file_trust (answered, vayu::http::FileAccessPolicy{});
        const json expected =
        comparable (nlohmann::ordered_json::parse (entry.at ("expected").dump ()));
        EXPECT_EQ (comparable (nlohmann::ordered_json::parse (answered.dump ())), expected)
        << "case: " << name;
    }
}

/**
 * The other half of the fixture: the `POST /import/apply` payload each result
 * flattens to (issue #877).
 *
 * `POST /import` builds it here and the app builds it in `orchestrator.ts`,
 * because the app applies a *previewed and filtered* result and this route
 * applies a document. Two implementations of one mapping is the repo's
 * hand-rolled-copy defect in the one place a missing field is silent - a
 * request that imported without its examples looks exactly like a document
 * that documented none - so both are pinned to the same `payload`, this side
 * here and the renderer's in `orchestrator.payload-conformance.test.ts`.
 */
TEST (ImportApplyPayload, MatchesWhatTheOrchestratorFlattens) {
    const json fixture = read_fixture ();
    for (const json& entry : fixture.at ("cases")) {
        const std::string name = entry.at ("name").get<std::string> ();
        ASSERT_TRUE (entry.contains ("payload")) << name << ": no payload recorded";
        const nlohmann::ordered_json result =
        nlohmann::ordered_json::parse (entry.at ("expected").dump ());
        EXPECT_EQ (json::parse (vayu::core::import_apply_payload (result).dump ()),
        entry.at ("payload"))
        << "case: " << name;
    }
}

/// The `order` each section of @p payload gives the item named @p name.
int payload_order (const json& payload, const char* section, const std::string& name) {
    for (const json& item : payload.at (section)) {
        if (item.at ("name") == name) {
            return item.value ("order", -1);
        }
    }
    ADD_FAILURE () << "no " << section << " item named " << name;
    return -1;
}

/// A draft with nothing beneath it, named @p name, as every importer emits one.
nlohmann::ordered_json bare_draft (const std::string& name) {
    return nlohmann::ordered_json{ { "name", name }, { "description", "" },
        { "variables", nlohmann::ordered_json::object () },
        { "auth", { { "mode", "none" } } },
        { "children", nlohmann::ordered_json::array () },
        { "requests", nlohmann::ordered_json::array () } };
}

nlohmann::ordered_json bare_request (const std::string& name) {
    return nlohmann::ordered_json{ { "name", name }, { "description", "" },
        { "method", "GET" }, { "url", "https://x/" + name },
        { "params", nlohmann::ordered_json::array () },
        { "headers", nlohmann::ordered_json::array () },
        { "body", { { "mode", "none" } } }, { "auth", { { "mode", "inherit" } } } };
}

// A parent's folders and requests share one `order` space (#2535). A draft
// that states no `order` keeps the display it always had, its folders first and
// its requests after them, and a draft that states one is placed by it.
TEST (ImportApplyPayload, NumbersFoldersAndRequestsInOneSpace) {
    nlohmann::ordered_json root = bare_draft ("root");
    root["requests"].push_back (bare_request ("first"));
    root["requests"].push_back (bare_request ("second"));
    root["children"].push_back (bare_draft ("folder"));
    nlohmann::ordered_json result{ { "collections", nlohmann::ordered_json::array ({ root }) },
        { "environments", nlohmann::ordered_json::array () } };

    json payload = json::parse (vayu::core::import_apply_payload (result).dump ());
    EXPECT_EQ (payload_order (payload, "collections", "folder"), 0);
    EXPECT_EQ (payload_order (payload, "requests", "first"), 1);
    EXPECT_EQ (payload_order (payload, "requests", "second"), 2);
    EXPECT_EQ (payload_order (payload, "collections", "root"), -1)
    << "a root states no order";

    // Stated: the second request first, the folder between, gaps closed.
    auto& stated                   = result["collections"][0];
    stated["requests"][0]["order"] = 7;
    stated["requests"][1]["order"] = 2;
    stated["children"][0]["order"] = 5;
    payload = json::parse (vayu::core::import_apply_payload (result).dump ());
    EXPECT_EQ (payload_order (payload, "requests", "second"), 0);
    EXPECT_EQ (payload_order (payload, "collections", "folder"), 1);
    EXPECT_EQ (payload_order (payload, "requests", "first"), 2);
}

TEST (ImportParse, RefusesADocumentNoFormatClaims) {
    const ImportParse parsed = parse_import (R"({"hello":"world"})", {}, {});
    EXPECT_FALSE (parsed.ok ());
    EXPECT_TRUE (parsed.unrecognised);
    EXPECT_EQ (parsed.error, "Unrecognised format");
}

TEST (ImportParse, RefusesBytesThatAreNeitherJsonNorYaml) {
    // Told apart from "unrecognised" deliberately: one says Vayu does not read
    // this kind of file, the other that this file is broken.
    const ImportParse parsed = parse_import ("{ unclosed: [1, 2", {}, {});
    EXPECT_FALSE (parsed.ok ());
    EXPECT_FALSE (parsed.unrecognised);
    EXPECT_NE (parsed.error.find ("Couldn't read the document"), std::string::npos);
}

TEST (ImportParse, NamesTheFieldOfAMalformedInsomniaExport) {
    const ImportParse parsed = parse_import (
    R"({"_type":"export","__export_format":4,"resources":"nope"})", {}, {});
    EXPECT_FALSE (parsed.ok ());
    EXPECT_FALSE (parsed.unrecognised);
    EXPECT_EQ (parsed.error, "Malformed Insomnia export: `resources` must be an array");
}

TEST (ImportParse, StepsOverACycleInAnInsomniaFolderTree) {
    // Insomnia cannot emit one (`parentId` is a single edge), but a mangled file
    // can, and an unguarded walk answers that by running out of stack.
    const ImportParse parsed = parse_import (R"({"_type":"export","__export_format":4,"resources":[
        {"_id":"wrk","_type":"workspace","name":"W"},
        {"_id":"a","_type":"request_group","parentId":"wrk","name":"A"},
        {"_id":"wrk2","_type":"request_group","parentId":"a","name":"B"}]})",
    {}, {});
    ASSERT_TRUE (parsed.ok ()) << parsed.error;
    EXPECT_EQ (parsed.result.at ("meta").at ("folderCount"), 2);
}

class ImportParseRoute : public ::testing::Test {
    protected:
    static constexpr const char* DB_PATH = "test_import_parse_route.db";

    void SetUp () override {
        cleanup ();
        db_ = std::make_unique<vayu::db::Database> (DB_PATH);
        db_->init ();
    }
    void TearDown () override {
        db_.reset ();
        cleanup ();
    }
    static void cleanup () {
        vayu::tests::remove_database_files (DB_PATH);
    }

    std::unique_ptr<vayu::db::Database> db_;
};

// The preview reads each imported path's `unresolved` as this machine's roots
// and grants decide it (#2356), to offer "Allow folder" for the ones it would
// not send. Mutation check: drop the `derive_import_file_trust` call in
// `import_parse_response` and neither body carries the key.
TEST_F (ImportParseRoute, DerivesEachImportedPathsTrust) {
    const std::filesystem::path dir = std::filesystem::current_path () / "import-trust";
    std::filesystem::create_directories (dir);
    std::ofstream (dir / "picked.bin") << "picked";
    const std::string picked = std::filesystem::canonical (dir / "picked.bin").string ();
    vayu::FileGrant grant;
    grant.id   = "fgrant_1";
    grant.path = picked;
    db_->save_file_grant (grant);

    const auto upload = [] (const std::string& name, const std::string& src) {
        return json{ { "name", name },
            { "request",
            { { "method", "PUT" }, { "url", "https://x/" + name },
            { "body", { { "mode", "file" }, { "file", { { "src", src } } } } } } } };
    };
    const json document = { { "info", { { "name", "C" }, { "schema", "v2.1.0" } } },
        { "item", json::array ({ upload ("picked", picked), upload ("elsewhere", "/no/such/b.bin") }) } };
    auto [status, body] = vayu::http::routes::import_parse_response (
    *db_, json{ { "content", document.dump () } });
    ASSERT_EQ (status, 200) << body.dump ();
    const json& requests = body.at ("collections").at (0).at ("requests");
    ASSERT_EQ (requests.size (), 2u) << body.dump ();
    EXPECT_EQ (requests.at (0).at ("body").at ("file").at ("unresolved"), false)
    << body.dump ();
    EXPECT_EQ (requests.at (1).at ("body").at ("file").at ("unresolved"), true)
    << body.dump ();
    std::filesystem::remove_all (dir);
}

TEST_F (ImportParseRoute, AnswersTheWholeImportResult) {
    auto [status, body] = vayu::http::routes::import_parse_response (*db_,
    json{ { "content", R"({"info":{"name":"C","schema":"v2.1.0"},"item":[]})" } });
    ASSERT_EQ (status, 200) << body.dump ();
    EXPECT_EQ (body.at ("meta").at ("format"), "Postman Collection v2.1");
    EXPECT_TRUE (body.contains ("collections"));
    EXPECT_TRUE (body.contains ("environments"));
    EXPECT_TRUE (body.contains ("globals"));
}

TEST_F (ImportParseRoute, RefusesADocumentOverTheStoredCap) {
    // Reuses `maxSpecDocumentBytes` rather than growing a second knob: the whole
    // document is read into memory whatever format claims it, and an OpenAPI
    // import stores exactly these bytes.
    auto entry = db_->get_config_entry ("maxSpecDocumentBytes");
    ASSERT_HAS_VALUE (entry);
    entry->value = "64";
    db_->save_config_entry (*entry);
    auto [status, body] = vayu::http::routes::import_parse_response (
    *db_, json{ { "content", std::string (200, 'x') } });
    EXPECT_EQ (status, 413);
    EXPECT_NE (body.at ("error").at ("message").get<std::string> ().find (
               "maxSpecDocumentBytes"),
    std::string::npos);
}

TEST_F (ImportParseRoute, PassesTheUnrecognisedSentenceThrough) {
    auto [status, body] = vayu::http::routes::import_parse_response (
    *db_, json{ { "content", R"({"a":1})" } });
    EXPECT_EQ (status, 400);
    EXPECT_EQ (body.at ("error").at ("message"), "Unrecognised format");
}

TEST_F (ImportParseRoute, RefusesAnEmptyOrAbsentDocument) {
    EXPECT_EQ (vayu::http::routes::import_parse_response (*db_, json::object ()).first, 400);
    EXPECT_EQ (
    vayu::http::routes::import_parse_response (*db_, json{ { "content", "" } }).first, 400);
    EXPECT_EQ (vayu::http::routes::import_parse_response (
               *db_, json{ { "content", "{}" }, { "importScripts", "yes" } })
               .first,
    400);
}

TEST_F (ImportParseRoute, ReadsADocumentIntoADomForTheRefBundler) {
    auto [status, body] = vayu::http::routes::import_document_response (
    *db_, json{ { "content", "openapi: 3.0.0\npaths:\n  /a:\n    get: {}\n" } });
    ASSERT_EQ (status, 200) << body.dump ();
    EXPECT_EQ (body.at ("document").at ("openapi"), "3.0.0");
    // Order is the document's, which is the whole reason a YAML reader in the
    // renderer could not answer this question the same way.
    EXPECT_TRUE (body.at ("document").at ("paths").contains ("/a"));
}

TEST_F (ImportParseRoute, PersistsTheWholeTreeInOneCall) {
    auto [status, body] = vayu::http::routes::import_response (
    *db_, json{ { "content", R"({"info":{"name":"CB","schema":"v2.1.0"},"item":[
        {"name":"Ping","request":{"method":"GET","url":"https://x/ping"}}]})" } });
    ASSERT_EQ (status, 200) << body.dump ();
    EXPECT_EQ (body.at ("collections"), 1);
    EXPECT_EQ (body.at ("requests"), 1);
    EXPECT_EQ (body.at ("meta").at ("format"), "Postman Collection v2.1");
    // Every temp id the flattening minted comes back mapped to a real one.
    EXPECT_TRUE (body.at ("idMap").contains ("c1"));
    EXPECT_TRUE (body.at ("idMap").contains ("r1"));
    EXPECT_EQ (db_->get_collections ().size (), 1U);
}

/// The fixture document whose requests sit before, between and after
/// sub-folders, at three depths - Postman's own `collection-v2.json` shape.
std::string interleaved_postman_document () {
    const json fixture = read_fixture ();
    for (const json& entry : fixture.at ("cases")) {
        if (entry.at ("name") == "postman-interleaved") {
            return entry.at ("document").get<std::string> ();
        }
    }
    ADD_FAILURE () << "no postman-interleaved case in the fixture";
    return {};
}

// Postman runs a folder's items in document order, descending into a
// sub-folder where it sits (#2535); the import keeps that order, so the
// sidebar lists it and a recursive run visits it the same way. Mutation
// check: give `flatten` one counter per kind again and this reds.
TEST_F (ImportParseRoute, APostmanCollectionKeepsItsDocumentOrder) {
    auto [status, body] = vayu::http::routes::import_response (
    *db_, json{ { "content", interleaved_postman_document () } });
    ASSERT_EQ (status, 200) << body.dump ();
    const std::string root = body.at ("idMap").at ("c1").get<std::string> ();

    using vayu::tests::listed_children;
    EXPECT_EQ (listed_children (*db_, root),
    (std::vector<std::string>{ "request:Log in", "request:Who am I",
    "folder:This is a folder", "request:Log out" }));
    const std::string folder = vayu::tests::child_folder_id (*db_, root, "This is a folder");
    EXPECT_EQ (listed_children (*db_, folder),
    (std::vector<std::string>{
    "request:First", "request:Second", "request:Third", "folder:Nested" }));
    const std::string nested = vayu::tests::child_folder_id (*db_, folder, "Nested");
    EXPECT_EQ (listed_children (*db_, nested),
    (std::vector<std::string>{ "folder:Users", "request:Between", "folder:Orders" }));

    std::vector<std::string> run;
    for (const auto& request : db_->get_requests_in_subtree (root)) {
        run.push_back (request.name);
    }
    EXPECT_EQ (run,
    (std::vector<std::string>{ "Log in", "Who am I", "First", "Second", "Third",
    "List users", "Between", "Log out" }));
}

// A collection of folders only lists them as the document does, numbered
// from 0 as before #2535.
TEST_F (ImportParseRoute, APostmanCollectionOfFoldersOnlyIsUnchanged) {
    auto [status, body] = vayu::http::routes::import_response (
    *db_, json{ { "content", R"({"info":{"name":"F","schema":"v2.1.0"},"item":[
        {"name":"B","item":[]},{"name":"A","item":[]}]})" } });
    ASSERT_EQ (status, 200) << body.dump ();
    const std::string root = body.at ("idMap").at ("c1").get<std::string> ();
    EXPECT_EQ (vayu::tests::listed_children (*db_, root),
    (std::vector<std::string>{ "folder:B", "folder:A" }));
    for (const char* temp : { "c2", "c3" }) {
        const auto row = db_->get_collection (body.at ("idMap").at (temp));
        ASSERT_HAS_VALUE (row) << temp;
        EXPECT_EQ (row->order, temp == std::string ("c2") ? 0 : 1);
    }
}

/// A plan whose samplers sit before, between and after controllers, three
/// levels deep, with a disabled sampler and a second ThreadGroup in the way.
const char* INTERLEAVED_JMETER_PLAN = R"jmx(<?xml version="1.0"?>
<jmeterTestPlan jmeter="5.6.3"><hashTree>
  <TestPlan testname="P"/><hashTree>
    <ThreadGroup testname="G1"/><hashTree>
      <HTTPSamplerProxy testname="A"><stringProp name="HTTPSampler.path">/a</stringProp></HTTPSamplerProxy><hashTree/>
      <LoopController testname="Loop"/><hashTree>
        <HTTPSamplerProxy testname="X"><stringProp name="HTTPSampler.path">/x</stringProp></HTTPSamplerProxy><hashTree/>
        <TransactionController testname="Inner"/><hashTree>
          <HTTPSamplerProxy testname="Y"><stringProp name="HTTPSampler.path">/y</stringProp></HTTPSamplerProxy><hashTree/>
        </hashTree>
        <HTTPSamplerProxy testname="Z"><stringProp name="HTTPSampler.path">/z</stringProp></HTTPSamplerProxy><hashTree/>
      </hashTree>
      <HTTPSamplerProxy testname="Off" enabled="false"><stringProp name="HTTPSampler.path">/off</stringProp></HTTPSamplerProxy><hashTree/>
      <HTTPSamplerProxy testname="B"><stringProp name="HTTPSampler.path">/b</stringProp></HTTPSamplerProxy><hashTree/>
    </hashTree>
    <ThreadGroup testname="G2"/><hashTree>
      <HTTPSamplerProxy testname="C"><stringProp name="HTTPSampler.path">/c</stringProp></HTTPSamplerProxy><hashTree/>
    </hashTree>
  </hashTree>
</hashTree></jmeterTestPlan>
)jmx";

// A JMeter plan runs its elements in tree order, a controller where it sits
// (#2573); the import keeps that order, so the sidebar lists it and a
// recursive run visits it the same way. Mutation check: stop stamping `order`
// in jmeter_import.cpp's `Sink` and this reds.
TEST_F (ImportParseRoute, AJmeterPlanKeepsItsTreeOrder) {
    auto [status, body] = vayu::http::routes::import_response (
    *db_, json{ { "content", INTERLEAVED_JMETER_PLAN } });
    ASSERT_EQ (status, 200) << body.dump ();
    const std::string root = body.at ("idMap").at ("c1").get<std::string> ();

    using vayu::tests::listed_children;
    EXPECT_EQ (listed_children (*db_, root),
    (std::vector<std::string>{ "request:A", "folder:Loop", "request:B", "request:C" }));
    const std::string loop = vayu::tests::child_folder_id (*db_, root, "Loop");
    EXPECT_EQ (listed_children (*db_, loop),
    (std::vector<std::string>{ "request:X", "folder:Inner", "request:Z" }));

    std::vector<std::string> run;
    for (const auto& request : db_->get_requests_in_subtree (root)) {
        run.push_back (request.name);
    }
    EXPECT_EQ (run, (std::vector<std::string>{ "A", "X", "Y", "Z", "B", "C" }));
}

