/// What an import writes is what the write routes accept: a binary body
/// persists through `POST /import` with its file reference intact.
TEST_F (ImportParseRoute, PersistsAnImportedBinaryBody) {
    auto [status, body] = vayu::http::routes::import_response (
    *db_, json{ { "content", R"({"info":{"name":"CB","schema":"v2.1.0"},"item":[
        {"name":"Put","request":{"method":"PUT","url":"https://x/put",
            "body":{"mode":"file","file":{"src":"/data/a.bin"}}}}]})" } });
    ASSERT_EQ (status, 200) << body.dump ();
    const auto collections = db_->get_collections ();
    ASSERT_EQ (collections.size (), 1U);
    const auto requests = db_->get_requests_in_collection (collections[0].id);
    ASSERT_EQ (requests.size (), 1U);
    EXPECT_EQ (json::parse (requests[0].body),
    json::parse (R"({"mode":"binary","file":{"src":"/data/a.bin","fileName":"a.bin"}})"));
}

/**
 * The globals half, which is the one write outside the transaction.
 *
 * It is also the one that can vanish silently: `Globals` is a singleton
 * addressed by a fixed id, so a row saved without it is a row `get_globals`
 * never finds - the import would report four variables written and the scope
 * would still be empty. Reverting the `row.id` line reddens the first
 * assertion.
 */
TEST_F (ImportParseRoute, WritesAGlobalsExportIntoTheGlobalScopeAndMergesASecond) {
    const auto import_globals = [this] (const std::string& values) {
        auto [status, body] = vayu::http::routes::import_response (*db_,
        json{ { "content",
        R"({"_postman_variable_scope":"globals","values":)" + values + "}" } });
        EXPECT_EQ (status, 200) << body.dump ();
    };
    // Without the import's `createdAt` stamps, which
    // `AReimportedGlobalKeepsItsStoredCreatedAt` pins.
    const auto stored = [this] {
        const auto row = db_->get_globals ();
        return without_created_at (row ? json::parse (row->variables) : json::object ());
    };

    import_globals (R"([{"key":"host","value":"a"},{"key":"token","value":"b"}])");
    EXPECT_EQ (stored (),
    (json{ { "host", { { "value", "a" }, { "enabled", true } } },
    { "token", { { "value", "b" }, { "enabled", true } } } }));

    // A second import **merges**: the engine has no merge verb, and writing the
    // import's globals alone would delete every global the user already had.
    // The imported value wins a collision - the caller asked for this file's
    // variables, and skipping them would be the silent no-op.
    import_globals (R"([{"key":"host","value":"z"},{"key":"extra","value":"c"}])");
    EXPECT_EQ (stored (),
    (json{ { "host", { { "value", "z" }, { "enabled", true } } },
    { "token", { { "value", "b" }, { "enabled", true } } },
    { "extra", { { "value", "c" }, { "enabled", true } } } }));
}

/**
 * A `POST /globals` landing inside the import's merge is kept beside the
 * imported variables (#1906). The competing save has the renderer's shape - its
 * view of the set plus one edit, saved whole - so it keeps the import's
 * variables only by reading after the import's write, and the import keeps the
 * save only by holding the lock from its read to its write.
 */
TEST_F (ImportParseRoute, KeepsAGlobalsSaveThatLandsDuringTheMerge) {
    int competing_status = 0;
    vayu::tests::CompetingWriter renderer ([&] {
        const auto row = db_->get_globals ();
        json variables = row ? json::parse (row->variables) : json::object ();
        variables["session"] = { { "value", "s" }, { "enabled", true } };
        const json save      = { { "variables", variables } };
        competing_status =
        vayu::http::routes::save_globals_response (*db_, save).first;
    });

    auto [status, body] = vayu::http::routes::import_response (*db_,
    json{ { "content", R"({"_postman_variable_scope":"globals","values":[{"key":"host","value":"a"}]})" } },
    renderer.probe ());
    ASSERT_EQ (status, 200) << body.dump ();
    renderer.join ();
    EXPECT_EQ (competing_status, 200);

    const auto row = db_->get_globals ();
    ASSERT_HAS_VALUE (row);
    EXPECT_EQ (without_created_at (json::parse (row->variables)),
    (json{ { "host", { { "value", "a" }, { "enabled", true } } },
    { "session", { { "value", "s" }, { "enabled", true } } } }));
}

/**
 * A re-import replaces a global's value but not its place in the list (#3252):
 * the parse stamps every row it reads, and an existing variable is never
 * restamped, so a stored row keeps its `createdAt` and a row stored without
 * one stays without. Only a new name takes the import's stamp. Mutation check:
 * merge the imported row over the stored one whole in `merge_globals_locked`
 * and the first two assertions fail.
 */
TEST_F (ImportParseRoute, AReimportedGlobalKeepsItsStoredCreatedAt) {
    const auto [saved, saved_body] = vayu::http::routes::save_globals_response (*db_,
    json{ { "variables",
    { { "host", { { "value", "a" }, { "enabled", true }, { "createdAt", 5 } } },
    { "legacy", { { "value", "l" }, { "enabled", true } } } } } });
    ASSERT_EQ (saved, 200) << saved_body.dump ();

    auto [status, body] = vayu::http::routes::import_response (
    *db_, json{ { "content", R"({"_postman_variable_scope":"globals","values":[
        {"key":"host","value":"z"},{"key":"legacy","value":"m"},{"key":"extra","value":"c"}]})" } });
    ASSERT_EQ (status, 200) << body.dump ();

    const auto row = db_->get_globals ();
    ASSERT_HAS_VALUE (row);
    const json stored = json::parse (row->variables);
    EXPECT_EQ (stored.at ("host").at ("createdAt"), 5) << stored.dump ();
    EXPECT_FALSE (stored.at ("legacy").contains ("createdAt")) << stored.dump ();
    EXPECT_EQ (stored.at ("host").at ("value"), "z");
    EXPECT_EQ (stored.at ("legacy").at ("value"), "m");
    EXPECT_TRUE (stored.at ("extra").at ("createdAt").is_number_integer ())
    << stored.dump ();
}

TEST_F (ImportParseRoute, RefusesBytesThatAreNotADocument) {
    auto [status, body] = vayu::http::routes::import_document_response (
    *db_, json{ { "content", "{ unclosed: [1, 2" } });
    EXPECT_EQ (status, 400);
    EXPECT_NE (body.at ("error").at ("message").get<std::string> ().find (
               "Invalid 'content'"),
    std::string::npos);
}

